import math
from itertools import combinations

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def count_divisors(n):
    return len(get_divisors(n))

def solve_search():
    # Search up to N_MAX = 500 initially, focusing on low tau(n)
    N_MAX = 500

    # Target tau(n) values
    target_taus = [6, 7, 8, 9, 10]

    solutions = []

    print(f"Starting systematic search for n > 100 up to {N_MAX} with tau(n) in {target_taus}...")

    for n in range(101, N_MAX + 1):
        tau_n = count_divisors(n)

        if tau_n not in target_taus:
            continue

        divs = get_divisors(n)

        # We need at least 5 divisors (1, d2, d3, d4, d5, ...)
        if len(divs) < 5:
            continue

        d2 = divs[1]
        d3 = divs[2]
        d5 = divs[4]

        # Check the condition: n = d2*d3 + d2*d5 + d3*d5
        calculated_n = d2 * d3 + d2 * d5 + d3 * d5

        if calculated_n == n:
            # Solution found
            print(f"Found solution: n = {n}. Divisors: {divs}. d2={d2}, d3={d3}, d5={d5}. tau(n) = {tau_n}")
            solutions.append(tau_n)

    return sorted(list(set(solutions)))

possible_taus = solve_search()
print(f"\nAll found possible values for tau(n) are: {possible_taus}")

